SELECT CASE WHEN city IN ('Singapore', 'Bangkok') THEN 'group_a' ELSE 'other' END AS city_group, region, COUNT(*) AS cnt, SUM(CASE WHEN region = 'East' THEN sqft ELSE 0 END) AS east_sqft, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(region))) AS region_values FROM stores GROUP BY CASE WHEN city IN ('Singapore', 'Bangkok') THEN 'group_a' ELSE 'other' END, region HAVING SUM(CASE WHEN city = 'Singapore' THEN sqft ELSE 0 END) < 29 ORDER BY cnt ASC, east_sqft DESC, city_group ASC, region ASC LIMIT 5
